func (r *OrderResolver) Legs(ctx context.Context, obj *order.Order) ([]*gqlmodel.OrderLeg, error) {
	legs := make([]*gqlmodel.OrderLeg, 0, len(obj.Shipments))
	for _, shp := range obj.Shipments {
		if shp == nil {
			continue
		}
		legs = append(legs, &gqlmodel.OrderLeg{
			ID:                  shp.ID.String(),
			ProNumber:           shp.ProNumber,
			Status:              gqlmodel.ShipmentStatus(shp.Status),
			BOL:                 gqlscalar.StrPtr(shp.BOL),
			FreightChargeAmount: shp.FreightChargeAmount.Decimal.String(),
			TotalChargeAmount:   shp.TotalChargeAmount.Decimal.String(),
		})
	}
	return legs, nil
}

func (r *OrderResolver) Charges(ctx context.Context, obj *order.Order) ([]*gqlmodel.OrderCharge, error) {
	charges := make([]*gqlmodel.OrderCharge, 0, len(obj.Charges))
	for _, charge := range obj.Charges {
		if charge == nil {
			continue
		}
		allocations := charge.Allocations
		if allocations == nil {
			allocations = []*shipmentdomain.ChargeAllocation{}
			if loadercore.Available(ctx) {
				loaded, loadErr := operationsloaders.ChargeAllocationsByOrderChargeID(ctx, charge.ID.String())
				if loadErr != nil {
					return nil, loadErr
				}
				allocations = loaded
			}
		}
		var invoicedAt *int
		if charge.InvoicedAt != 0 {
			at := int(charge.InvoicedAt)
			invoicedAt = &at
		}
		charges = append(charges, &gqlmodel.OrderCharge{
			ID:          charge.ID.String(),
			OrderID:     charge.OrderID.String(),
			Description: charge.Description,
			Amount:      charge.Amount.String(),
			InvoiceID:   gqlid.IDPtr(charge.InvoiceID),
			InvoicedAt:  invoicedAt,
			Version:     int(charge.Version),
			CreatedAt:   int(charge.CreatedAt),
			Allocations: allocations,
		})
	}
	return charges, nil
}

func (r *QueryResolver) Orders(ctx context.Context, input gqlmodel.DataTableConnectionInput) (*gqlmodel.OrderConnection, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceOrder, permission.OpRead)
	if err != nil {
		return nil, err
	}

	tableInput, err := gqlconnection.DataTableConnectionFromGraphQL(ctx, &input, resolvercore.TenantInfo(authCtx))
	if err != nil {
		return nil, err
	}

	result, err := r.OrderService.ListConnection(
		ctx,
		&orderports.ListOrdersConnectionRequest{
			Filter:       tableInput.Filter,
			Cursor:       tableInput.Cursor,
			OrderColumns: orderColumns(ctx, "edges.node"),
		},
	)
	if err != nil {
		return nil, err
	}

	return orderConnectionToModel(result)
}

